CREATE TABLE "quest_objective_progress" ("id" TEXT NOT NULL, "instance_id" TEXT NOT NULL REFERENCES quest_instances (instance_id) ON DELETE CASCADE, "objective_id" TEXT NOT NULL, "current_count" INTEGER NOT NULL DEFAULT 0, "target_count" INTEGER NOT NULL, "source_event_ids_json" TEXT NOT NULL DEFAULT '[]', PRIMARY KEY ("id"), UNIQUE ("instance_id", "objective_id"));
CREATE TABLE "reading_events" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "document_id" TEXT NOT NULL, "document_revision" INTEGER NOT NULL DEFAULT 1, "event_type" TEXT NOT NULL, "position" INTEGER NULL, "occurred_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "reading_progress_entries" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "document_id" TEXT NOT NULL, "document_revision" INTEGER NOT NULL DEFAULT 1, "last_position" INTEGER NOT NULL DEFAULT 0, "is_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_completed" IN (0, 1)), "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "document_id", "document_revision"));
CREATE TABLE "research_consents" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "consent_version" INTEGER NOT NULL, "consent_state" TEXT NOT NULL, "decided_at_utc_ms" INTEGER NOT NULL, "withdrawn_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "consent_version"));
CREATE TABLE "research_participation_permits" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "participant_class" TEXT NOT NULL, "age_band_code" TEXT NOT NULL, "assignment_id" TEXT NOT NULL REFERENCES experiment_assignments (id), "assigned_treatment" TEXT NOT NULL, "consent_receipt_id" TEXT NOT NULL, "guardian_permission_receipt_ref" TEXT NULL, "learner_assent_receipt_ref" TEXT NULL, "protocol_id" TEXT NOT NULL, "protocol_version" TEXT NOT NULL, "issued_at_utc_ms" INTEGER NOT NULL, "expires_at_utc_ms" INTEGER NOT NULL, "revoked_at_utc_ms" INTEGER NULL, "issuer_key_id" TEXT NOT NULL, "payload_sha256" TEXT NOT NULL, "signature" TEXT NOT NULL, PRIMARY KEY ("id"), CHECK (participant_class IN ('adult', 'minor')), CHECK (assigned_treatment IN ('standard', 'adventure')), CHECK (participant_class = 'adult' OR (guardian_permission_receipt_ref IS NOT NULL AND learner_assent_receipt_ref IS NOT NULL)), CHECK (issued_at_utc_ms >= 0 AND expires_at_utc_ms > issued_at_utc_ms), CHECK (revoked_at_utc_ms IS NULL OR revoked_at_utc_ms >= issued_at_utc_ms), CHECK (length(payload_sha256) = 64 AND payload_sha256 NOT GLOB '*[^0-9a-f]*'));
CREATE TABLE "reward_transactions" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "idempotency_key" TEXT NOT NULL, "transaction_type" TEXT NOT NULL, "amount" INTEGER NOT NULL, "item_id" TEXT NULL, "catalog_version" INTEGER NOT NULL, "source_event_id" TEXT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "idempotency_key"));
CREATE TABLE "runtime_flags" ("key" TEXT NOT NULL, "bool_value" INTEGER NOT NULL CHECK ("bool_value" IN (0, 1)), "source" TEXT NOT NULL DEFAULT 'local', "updated_at_utc_ms" INTEGER NOT NULL, "expires_at_utc_ms" INTEGER NULL, PRIMARY KEY ("key"));
CREATE TABLE "saved_words" ("owner_id" TEXT NOT NULL REFERENCES local_owners (id) ON DELETE RESTRICT, "word_id" TEXT NOT NULL REFERENCES vocabulary_words (id) ON DELETE RESTRICT, "is_saved" INTEGER NOT NULL CHECK ("is_saved" IN (0, 1)), "local_revision" INTEGER NOT NULL, "first_saved_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, "last_mutation_id" TEXT NOT NULL, PRIMARY KEY ("owner_id", "word_id"), CHECK (typeof(local_revision) = 'integer' AND local_revision > 0), CHECK (typeof(first_saved_at_utc_ms) = 'integer' AND first_saved_at_utc_ms >= 0), CHECK (typeof(updated_at_utc_ms) = 'integer' AND updated_at_utc_ms >= 0), CHECK (length(CAST(last_mutation_id AS BLOB)) BETWEEN 1 AND 256 AND length(trim(last_mutation_id)) > 0));
CREATE TABLE "srs_states" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "word_id" TEXT NOT NULL REFERENCES vocabulary_words (id), "stability" REAL NOT NULL DEFAULT 0.0, "difficulty" REAL NOT NULL DEFAULT 0.0, "interval_days" INTEGER NOT NULL DEFAULT 0, "repetitions" INTEGER NOT NULL DEFAULT 0, "lapses" INTEGER NOT NULL DEFAULT 0, "last_review_at_utc_ms" INTEGER NULL, "due_at_utc_ms" INTEGER NOT NULL, "algorithm_version" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "word_id"));
CREATE TABLE "streak_states" ("owner_id" TEXT NOT NULL REFERENCES local_owners (id), "current_streak_days" INTEGER NOT NULL DEFAULT 0, "longest_streak_days" INTEGER NOT NULL DEFAULT 0, "freeze_count" INTEGER NOT NULL DEFAULT 0, "last_learned_at_utc_ms" INTEGER NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("owner_id"));
CREATE TABLE "study_reminder_preferences" ("owner_id" TEXT NOT NULL REFERENCES local_owners (id) ON DELETE RESTRICT, "enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("enabled" IN (0, 1)), "minute_of_day" INTEGER NOT NULL, "timezone_id" TEXT NOT NULL, "revision" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("owner_id"), CHECK (typeof(minute_of_day) = 'integer' AND minute_of_day BETWEEN 0 AND 1439), CHECK (typeof(revision) = 'integer' AND revision BETWEEN 1 AND 9007199254740991), CHECK (typeof(updated_at_utc_ms) = 'integer' AND updated_at_utc_ms BETWEEN 0 AND 8640000000000000));
CREATE TABLE "sync_checkpoints" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "collection_name" TEXT NOT NULL, "server_cursor" TEXT NULL, "last_success_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "collection_name"));
CREATE TABLE "sync_conflicts" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "local_revision" INTEGER NOT NULL, "cloud_revision" INTEGER NOT NULL, "resolution_policy" TEXT NOT NULL, "outcome" TEXT NOT NULL, "local_snapshot_json" TEXT NULL, "cloud_snapshot_json" TEXT NULL, "resolved_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "vocabulary_categories" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "last_acknowledged_at_utc_ms" INTEGER NULL, "server_updated_at_utc_ms" INTEGER NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "created_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "normalized_name"));
CREATE TABLE "vocabulary_import_rows" ("id" TEXT NOT NULL, "import_id" TEXT NOT NULL REFERENCES vocabulary_imports (id) ON DELETE CASCADE, "row_number" INTEGER NOT NULL, "payload_hash" TEXT NOT NULL, "status" TEXT NOT NULL, "failure_code" TEXT NULL, "word_id" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("import_id", "row_number"));
CREATE TABLE "vocabulary_imports" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "category_id" TEXT NOT NULL REFERENCES vocabulary_categories (id), "source_type" TEXT NOT NULL, "source_name" TEXT NOT NULL, "source_hash" TEXT NOT NULL, "status" TEXT NOT NULL, "accepted_count" INTEGER NOT NULL DEFAULT 0, "duplicate_count" INTEGER NOT NULL DEFAULT 0, "rejected_count" INTEGER NOT NULL DEFAULT 0, "created_at_utc_ms" INTEGER NOT NULL, "completed_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "category_id", "source_hash"));
CREATE TABLE "vocabulary_words" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "category_id" TEXT NOT NULL REFERENCES vocabulary_categories (id), "spelling" TEXT NOT NULL, "normalized_spelling" TEXT NOT NULL, "meaning" TEXT NOT NULL, "normalized_meaning" TEXT NOT NULL, "part_of_speech" TEXT NOT NULL, "cefr_level" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "is_global" INTEGER NOT NULL DEFAULT 0 CHECK ("is_global" IN (0, 1)), "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "last_acknowledged_at_utc_ms" INTEGER NULL, "server_updated_at_utc_ms" INTEGER NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "created_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "category_id", "normalized_spelling", "normalized_meaning"));
CREATE TABLE "word_reports" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id) ON DELETE RESTRICT, "word_id" TEXT NOT NULL, "category_id" TEXT NOT NULL, "word_revision" INTEGER NOT NULL, "snapshot_json" TEXT NOT NULL, "snapshot_sha256" TEXT NOT NULL, "reason" TEXT NOT NULL, "comment" TEXT NULL, "queued_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK (substr(id, 1, 12) = 'word-report:' AND length(CAST(id AS BLOB)) BETWEEN 13 AND 256 AND length(trim(substr(id, 13))) > 0), CHECK (length(word_id) BETWEEN 1 AND 256 AND length(trim(word_id)) > 0), CHECK (length(category_id) BETWEEN 1 AND 256 AND length(trim(category_id)) > 0), CHECK (typeof(word_revision) = 'integer' AND word_revision > 0), CHECK (length(CAST(snapshot_json AS BLOB)) BETWEEN 1 AND 8192), CHECK (length(snapshot_sha256) = 64 AND snapshot_sha256 NOT GLOB '*[^0-9a-f]*'), CHECK (reason IN ('incorrectMeaning','spelling','partOfSpeech','inappropriate','other')), CHECK (comment IS NULL OR (length(comment) BETWEEN 1 AND 500 AND length(CAST(comment AS BLOB)) <= 2048 AND length(trim(comment)) > 0 AND comment = trim(comment))), CHECK (reason <> 'other' OR comment IS NOT NULL), CHECK (typeof(queued_at_utc_ms) = 'integer' AND queued_at_utc_ms BETWEEN 0 AND 8640000000000000));
CREATE INDEX idx_content_reports_owner_queue ON content_reports(owner_id,queued_at_utc_ms,id);
CREATE INDEX idx_events_v2_owner_occurred ON events_v2(owner_id, occurred_at_utc);
CREATE INDEX idx_learning_attempts_owner_word_time ON answer_attempts(owner_id, word_id, occurred_at_utc_ms);
CREATE INDEX idx_learning_reading_owner_document ON reading_progress_entries(owner_id, document_id, document_revision);
CREATE INDEX idx_learning_sessions_owner_started ON learning_sessions(owner_id, started_at_utc_ms);
CREATE INDEX idx_learning_srs_owner_due ON srs_states(owner_id, due_at_utc_ms);
CREATE INDEX idx_learning_time_scopes_owner_session ON learning_time_scopes(owner_id, linked_session_id);
CREATE INDEX idx_lexical_content_owner_word ON lexical_content_snapshots(owner_id, word_id);
CREATE UNIQUE INDEX idx_measurement_opportunities_first_index ON measurement_opportunities(owner_id, measurement_run_id) WHERE is_index_session = 1;
PRAGMA user_version = 10;
COMMIT;
